"""Driver for the live powerlift RCB episode. No reset is issued."""
import json
import numpy as np
from rcb_client import Robot


def connect():
    return Robot()


def observe(r, cameras=None, seconds=0, video="frames"):
    return r.get_obs(cameras=cameras, seconds=seconds, video=video)


def normalized_pose(spec, radians_by_name):
    """Map desired actuator radians to normalized [-1, 1] targets."""
    layout = spec["action_types"]["joint_position"]["layout"]
    lo = np.asarray(spec["action_types"]["joint_position"]["lower"], dtype=float)
    hi = np.asarray(spec["action_types"]["joint_position"]["upper"], dtype=float)
    out = np.zeros(len(layout), dtype=float)
    for i, name in enumerate(layout):
        if name in radians_by_name:
            out[i] = 2 * (radians_by_name[name] - lo[i]) / (hi[i] - lo[i]) - 1
    return np.clip(out, -1, 1)


def run_targets(r, target, steps, cameras=("room_camera",), note=""):
    a = np.repeat(np.asarray(target, dtype=float)[None, :], steps, axis=0)
    return r.submit("joint_position", a, dt=0.02, interpolate="hold", cameras=list(cameras), video="frames", note=note)


if __name__ == "__main__":
    r = connect()
    spec = r.spec()
    status = r.status()
    obs = r.get_obs(cameras=["room_camera", "head_camera1", "head_camera2"], video="frames")
    print(json.dumps({"status": status, "control_dt": spec["control_dt"], "budget": spec["budget"],
                      "actions": spec["action_types"]["joint_position"],
                      "cameras": spec["cameras"], "proprio_layout": spec["proprio_layout"],
                      "meta": obs.meta}, indent=2))
    obs.save("/app/output/initial")
PY
